html:
{%- import "erpnext/templates/print_formats/report_print_macros.html" as rp -%}
{%- set show_company = no_letterhead if no_letterhead is defined else not letter_head -%}
{%- set payable = report.report_name == "Accounts Payable" -%}
{%- set sign = -1 if payable else 1 -%}
{%- set by_due_date = (filters.ageing_based_on or "Due Date") == "Due Date" -%}
{%- set rows = [] -%}
{%- for row in data if row is mapping and row.voucher_no and not row.is_total_row and row.outstanding -%}
	{%- set ignore = rows.append(row) -%}
{%- endfor -%}
{%- set parties = rows | map(attribute="party") | unique | list -%}
{%- set party_type = filters.party_type or (rows[0].party_type if rows else ("Supplier" if payable else "Customer")) -%}
{%- set single = parties | length == 1 -%}
{%- set limits = (filters.range or "").split(",") | map("trim") | select | list if filters.range else [filters.range1, filters.range2, filters.range3, filters.range4] | select | map("string") | list -%}
{%- set limits = limits or ["30", "60", "90", "120"] -%}
{%- set labels = [_("Not Due")] -%}
{%- set low = namespace(value=0) -%}
{%- for limit in limits -%}
	{%- set ignore = labels.append(low.value ~ "-" ~ limit) -%}
	{%- set low.value = (limit | int) + 1 -%}
{%- endfor -%}
{%- set ignore = labels.append(_("{0} and above").format(low.value)) -%}
{%- set title = _("Bill-wise Pending") -%}
{%- set period = _("As on {0}").format(rp.date(filters.report_date)) -%}
{{ rp.styles() }}
<div class="rpf">
	{%- if show_company %}{{ rp.company_header(filters.company) }}{% endif %}
	{%- if single %}
	{{ rp.head(title, period, rp.party_name(party_type, parties[0]), rp.party_meta(party_type, parties[0])) }}
	{%- else %}
	{{ rp.head(title, period) }}
	{%- endif %}
	<table class="rpf-grid">
		<colgroup><col style="width: 80px"><col><col style="width: 80px"><col style="width: 74px"><col style="width: 128px"><col style="width: 128px"></colgroup>
		<thead>
			<tr>
				<th>{{ _("Date") }}</th>
				<th>{{ _("Reference No.") }}</th>
				<th>{{ _("Due On") }}</th>
				<th class="num">{{ _("Overdue") if by_due_date else _("Age") }}</th>
				<th class="num">{{ _("Bill Amount") }}</th>
				<th class="num">{{ _("Pending Amount") }}</th>
			</tr>
		</thead>
		<tbody>
			{%- for party in parties %}
			{%- set party_rows = rows | selectattr("party", "equalto", party) | list %}
			{%- if not single %}
			<tr class="group">
				<td colspan="3">{{ rp.party_name(party_type, party) }} <span class="muted regular">· {{ (_("{0} bill") if party_rows | length == 1 else _("{0} bills")).format(party_rows | length) }}</span></td>
				<td></td>
				<td></td>
				<td class="num">{{ rp.drcr(sign * (party_rows | map(attribute="outstanding") | map("float") | sum)) }}</td>
			</tr>
			{%- endif %}
			{%- for row in party_rows %}
			{%- set amount = row.invoiced or row.credit_note or row.paid or row.outstanding | abs %}
			<tr>
				<td class="nowrap">{{ rp.date(row.posting_date) }}</td>
				<td>
					{{ row.bill_no or row.voucher_no }}
					{%- if row.bill_no %} <span class="muted">· {{ row.voucher_no }}</span>{% endif %}
				</td>
				<td class="nowrap">{{ rp.date(row.due_date) }}</td>
				<td class="num {{ 'danger' if row.outstanding > 0 and row.age > 90 and by_due_date else '' }}">
					{%- if row.outstanding < 0 %}
					{%- elif not by_due_date or row.age > 0 %}{{ row.age }} {{ _("days") }}
					{%- else %}<span class="muted">{{ _("Not due") }}</span>{% endif -%}
				</td>
				<td class="num muted">{{ rp.drcr(sign * (amount if row.outstanding > 0 else -amount)) }}</td>
				<td class="num">{{ rp.drcr(sign * row.outstanding) }}</td>
			</tr>
			{%- endfor %}
			{%- else %}
			<tr><td colspan="6" class="rpf-empty">{{ _("No pending bills") }}</td></tr>
			{%- endfor %}
			{%- if rows %}
			<tr class="total">
				<td></td>
				<td>{{ _("Total") }}</td>
				<td></td>
				<td></td>
				<td></td>
				<td class="num"><span class="double">{{ rp.drcr(sign * (rows | map(attribute="outstanding") | map("float") | sum)) }}</span></td>
			</tr>
			{%- endif %}
		</tbody>
	</table>
	{%- if rows and by_due_date %}
	<table class="rpf-buckets">
		<tr>
			{%- for label in labels %}
			{%- set bucket = rows | map(attribute="range" ~ loop.index0) | map("float") | sum %}
			<td>
				<div class="rpf-label">{{ label }}</div>
				<div class="rpf-value {{ 'danger' if bucket and loop.index0 >= 4 else '' }}">{{ rp.money(bucket | abs) if bucket else "–" }}</div>
			</td>
			{%- endfor %}
		</tr>
	</table>
	{%- endif %}
	{%- if single and rows %}
	{%- set balance = rows | map(attribute="outstanding") | map("float") | sum %}
	<div class="rpf-box">
		<div class="rpf-label">
			{%- if (balance > 0) == payable %}{{ _("Balance payable to you as on {0}").format(rp.date(filters.report_date)) }}
			{%- else %}{{ _("Balance due from you as on {0}").format(rp.date(filters.report_date)) }}{% endif -%}
		</div>
		<div class="rpf-value rpf-value-lg">{{ frappe.utils.fmt_money(balance | abs, currency=rows[0].currency) }}</div>
		<div class="note">{{ frappe.utils.money_in_words(balance | abs, rows[0].currency) }}</div>
	</div>
	{%- endif %}
	{{ rp.footnote() }}
</div>
